-- Recipes. Seed recipes have no owner and are read-only for users.
insert into public.recipes
  (title, cuisine, instructions, prep_minutes, cook_minutes, base_servings,
   cost_bracket, diet_tags, source_url, image_url, image_credit, source_type)
select v.*, 'seed'
from (values
  ('Chicken Chop Suey Stir-Fry', 'Chinese', '1. Slice the chicken thinly. For extra-tender chicken, toss it with the baking soda, wait 20 minutes, then rinse and pat dry.
2. Stir the cornstarch into the soy sauce until smooth, then mix in the oyster sauce, mirin, sesame oil, white pepper and the water.
3. Cut the bok choy into 3-inch pieces, keeping the stems and leaves apart. Thinly slice the carrot.
4. Heat the oil in a wok or large skillet over high heat. Fry the chopped garlic and sliced onion for about 1 minute.
5. Add the chicken and cook for 1 minute, until it turns white on the outside.
6. Add the bok choy stems, carrot and mushrooms and stir-fry for 1 minute.
7. Add the bok choy leaves, bean sprouts and sauce. Toss for 1 to 2 minutes, until the sauce is glossy and thick and the vegetables are still crisp.
8. Serve right away with rice.', 10, 6, 2, '$$', array[]::text[], 'https://www.recipetineats.com/chicken-stir-fry/', 'https://images.unsplash.com/photo-1621515554656-3da68ba128b1?auto=format&fit=crop&w=1200&q=80', 'Photo by montatip lilitsanong on Unsplash'),
  ('Chicken Tikka Masala', 'Indian', '1. Cut the chicken into bite-size cubes. In a bowl, mix the yogurt, half the garlic, 1 tbsp ginger, 1 tsp garam masala, 1 tsp each of cumin, coriander, paprika and salt, a pinch of cayenne, the lemon juice and 1 tbsp oil. Coat the chicken and refrigerate for at least 3 hours (overnight is best).
2. Heat 1 tbsp oil in a nonstick pan over high heat. Sear the chicken in two batches for about 2 minutes per side, until charred in spots. It doesn''t need to be cooked through yet. Set aside.
3. Wipe the pan, lower the heat to medium-high and melt 2 tbsp butter with 3 tbsp oil. Cook the chopped onion, the remaining ginger and 1 tsp salt for 5 to 7 minutes, stirring, until golden and sweet.
4. Turn the heat to medium. Stir in the rest of the garlic and 1 tbsp paprika for 2 minutes, then add the turmeric, the remaining garam masala, 2 tsp coriander, 1 tsp cumin, the cardamom and a pinch of cayenne for 2 more minutes.
5. Pour in the tomato puree and water, bring to a simmer, cover and cook on low for 15 minutes.
6. Blend the sauce until smooth, return it to the pan and stir in the cream, sugar and remaining 3 tbsp butter.
7. Add the chicken and simmer for a few minutes, until cooked through. Serve over basmati rice with cilantro.', 15, 45, 4, '$$', array[]::text[], 'https://www.recipetineats.com/chicken-tikka-masala/', 'https://images.unsplash.com/photo-1565557623262-b51c2513a641?auto=format&fit=crop&w=1200&q=80', 'Photo by amirali mirhashemian on Unsplash'),
  ('Ratatouille', 'French', '1. Cut the eggplant into 3/4-inch cubes, toss with 1/2 tsp salt in a colander and let it drain for 30 minutes.
2. Blend the tomatoes until smooth.
3. In a large pan over medium-high heat, cook the eggplant in 2 tbsp oil for 4 to 5 minutes, until golden. Move it to a large pot.
4. In the same pan, cook each vegetable separately in 1 tbsp oil with a pinch of salt for about 3 minutes, adding each one to the pot: first the onion and garlic, then the bell peppers, then the zucchini. Keep them a little firm.
5. Add the blended tomato, thyme, olives, remaining salt and the pepper to the pot. Simmer uncovered over medium-high heat for 20 to 25 minutes, stirring now and then, until the vegetables are tender and the sauce has thickened.
6. Taste for salt, stir in the basil and serve with a drizzle of olive oil.', 15, 45, 8, '$', array['vegan', 'vegetarian']::text[], 'https://www.recipetineats.com/ratatouille/', 'https://images.unsplash.com/photo-1572453800999-e8d2d1589b7c?auto=format&fit=crop&w=1200&q=80', 'Photo by amirali mirhashemian on Unsplash'),
  ('Thai Green Curry with Chicken', 'Thai', '1. Heat the oil in a large pot over medium-high heat. Fry the curry paste for 2 to 3 minutes, until it looks dry and smells fragrant (stand back from the fumes). Store-bought paste often contains shrimp, so check the label if that matters to you.
2. Stir in the broth and coconut milk until the paste dissolves. Add the fish sauce, sugar and lime leaves and bring to a simmer.
3. Add the sliced chicken, lower the heat to medium and cook for 7 minutes at a gentle bubble.
4. Add the sliced eggplant and cook for 5 minutes, until soft. Taste and add more fish sauce or sugar if needed.
5. Add the snow peas for 2 minutes, then turn off the heat and stir in the basil and lime juice.
6. Serve over jasmine rice.', 15, 20, 4, '$$', array[]::text[], 'https://www.recipetineats.com/thai-green-curry/', 'https://images.unsplash.com/photo-1716959669858-11d415bdead6?auto=format&fit=crop&w=1200&q=80', 'Photo by You Le on Unsplash'),
  ('Chicken Enchiladas', 'Mexican', '1. Mix the onion powder, garlic powder, salt, cumin, paprika, oregano, black pepper and cayenne. This seasoning goes in both the sauce and the filling.
2. Sauce: heat 2 tbsp oil in a saucepan over medium heat, stir in the flour for 20 seconds, then whisk in 2 tbsp of the seasoning, the broth and the tomato puree. Simmer for about 4 minutes, whisking, until it thickens like a thin gravy.
3. Rub the chicken with 1 tbsp oil and the remaining seasoning. Sear it in 1 tbsp oil in a hot skillet for about 2 minutes per side, let it rest, then dice it.
4. In the same skillet, soften the chopped onion, garlic and bell pepper for 3 minutes. Stir in the refried beans, chicken, drained corn and water and cook for 2 minutes, until thick.
5. Heat the oven to 350°F. Fill each tortilla with about 2/3 cup filling and a little cheese, roll it up and place it seam-side down in a 9x13-inch dish spread with a little sauce.
6. Pour the rest of the sauce over, top with the remaining cheese and bake for 20 to 25 minutes, until bubbly and golden. Sprinkle with cilantro.', 20, 45, 8, '$$', array[]::text[], 'https://www.recipetineats.com/chicken-enchiladas/', 'https://images.unsplash.com/photo-1679605097294-ad339b020c0f?auto=format&fit=crop&w=1200&q=80', 'Photo by Diego Ramírez on Unsplash'),
  ('Quiche Lorraine', 'French', '1. Blind-bake a 9-inch pie crust following the package directions, then set the oven to 350°F.
2. Melt the butter in a skillet over medium-high heat and cook the chopped onion, garlic and bacon until the bacon is lightly golden. Drain on paper towels and let cool.
3. Whisk the eggs, cream, salt and pepper together.
4. Set the crust on a baking sheet. Spread the bacon mixture over the bottom, scatter the grated cheese on top, then slowly pour in the egg mixture.
5. Bake for 35 to 40 minutes, until golden on top but still slightly wobbly in the center.
6. Let it rest for 10 minutes before slicing.', 15, 55, 8, '$$', array[]::text[], 'https://www.recipetineats.com/quiche-lorraine/', 'https://images.unsplash.com/photo-1767065584177-9ceb902eec7a?auto=format&fit=crop&w=1200&q=80', 'Photo by Diego Arenas de Rodrigo on Unsplash'),
  ('Teriyaki Salmon Noodles', 'Japanese', '1. Stir the soy sauce, mirin, sake and sugar until the sugar dissolves. Cut the salmon into strips and toss with 1 tbsp of this sauce.
2. Cook the noodles according to the package (skip the flavor packet), then drain and rinse briefly.
3. Heat 1/2 tbsp oil in a large nonstick pan over high heat and sear the salmon for 1 1/2 minutes per side. Set aside.
4. Wipe the pan, add 1 tbsp oil and cook the sliced onion, garlic and broccolini stems for 1 to 2 minutes.
5. Add the noodles and half the sauce and toss for 2 minutes, then add the rest of the sauce.
6. Push the noodles aside, add the last 1/2 tbsp oil and the broccolini tops and toss for 1 1/2 minutes.
7. Off the heat, break the salmon into chunks over the noodles, toss gently and serve.', 5, 10, 2, '$$$', array['pescatarian']::text[], 'https://www.recipetineats.com/teriyaki-salmon/', 'https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?auto=format&fit=crop&w=1200&q=80', 'Photo by Caroline Attwood on Unsplash'),
  ('Chicken Parmesan', 'Italian', '1. Cut each chicken breast in half horizontally to make thinner cutlets. Season both sides with 1 tsp salt, 1/2 tsp pepper and 1/2 tsp Italian seasoning and chill for 30 minutes.
2. Sauce: heat 1 tbsp olive oil in a saucepan over medium heat and cook 2 cloves of minced garlic and the onion for 3 minutes. Add the pepper flakes and 1/4 tsp Italian seasoning, then the wine, and simmer until it''s mostly gone. Add the tomato puree, broth and a pinch of salt and pepper, cover and simmer on low for 10 minutes. Tear in half the basil.
3. Set up three shallow bowls: the flour; the eggs whisked with the last clove of garlic and a pinch of salt, pepper and Italian seasoning; and the panko mixed with 1/2 cup parmesan and the rest of the salt and pepper.
4. Coat each cutlet in flour, then egg, then the panko mixture, pressing so it sticks.
5. Heat about 3/4 inch of vegetable oil in a skillet to 350°F. Fry 2 or 3 cutlets at a time, about 2 minutes on the first side and 1 1/2 minutes on the second, then drain on a rack.
6. Heat the oven to 350°F. Put the cutlets on a baking sheet, spoon sauce over most of each one, top with the mozzarella and remaining parmesan, and drizzle with 1 tbsp olive oil.
7. Bake for about 15 minutes, until the cheese melts and browns in spots. Top with the rest of the basil.', 20, 40, 6, '$$', array[]::text[], 'https://www.recipetineats.com/chicken-parmigiana/', 'https://images.unsplash.com/photo-1632778149955-e80f8ceca2e8?auto=format&fit=crop&w=1200&q=80', 'Photo by Clark Douglas on Unsplash'),
  ('Lentil Soup', 'Mediterranean', '1. Warm the olive oil in a large pot over medium heat. Cook the chopped onion and carrots, stirring often, for about 5 minutes, until the onion is soft.
2. Add the garlic, cumin, curry powder and thyme and stir for 30 seconds, until fragrant. Add the drained tomatoes and cook for a few minutes more.
3. Add the rinsed lentils, broth, water, salt, pepper flakes and plenty of black pepper. Bring to a boil, then partly cover and simmer for about 30 minutes, until the lentils are tender.
4. Blend 2 cups of the soup until smooth (careful, it''s hot) and stir it back in for a creamier texture.
5. Add the chopped kale and cook for 5 minutes more. Off the heat, stir in the lemon juice and adjust the salt.
6. Leftovers keep for about 4 days in the fridge, or can be frozen.', 10, 45, 4, '$', array['vegan', 'vegetarian']::text[], 'https://cookieandkate.com/best-lentil-soup-recipe/', 'https://images.unsplash.com/photo-1605909388460-74ec8b204127?auto=format&fit=crop&w=1200&q=80', 'Photo by Jezebel Rose on Unsplash'),
  ('Chana Masala', 'Indian', '1. Heat the oil in a large pot over medium heat. Add the diced onion, cumin and a third of the salt and cook until soft and starting to brown.
2. Mash or finely chop the garlic, ginger, cilantro and chilies into a rough paste and stir it into the onions for a minute.
3. Add the coriander, chili powder and turmeric and stir to coat (add a splash of oil if the pan looks dry).
4. Add the tomatoes, drained chickpeas and the rest of the salt. If it looks too thick, add up to 1 cup water.
5. Bring to a strong simmer, then lower the heat and simmer for 15 to 20 minutes, until thick.
6. Taste and adjust the salt, heat or sweetness. Off the heat, stir in the garam masala and lemon juice. Serve with rice or naan.', 5, 25, 6, '$', array['vegan', 'vegetarian']::text[], 'https://minimalistbaker.com/easy-chana-masala/', 'https://images.unsplash.com/photo-1708782343809-0050c38b3a1a?auto=format&fit=crop&w=1200&q=80', 'Photo by Rimsha Noor on Unsplash'),
  ('Pasta e Fagioli', 'Italian', '1. Chop the bacon and fry it with the olive oil in a large pot over medium heat until crisp. Meanwhile, dice the onion, carrots and celery.
2. Lift out half the bacon and save it for the topping, leaving the rest and the fat in the pot.
3. Add the onion, carrots, celery, minced garlic, oregano, pepper flakes, salt and pepper and cook over medium-high heat for about 5 minutes, until the onion is soft.
4. Stir in the drained beans, crushed tomatoes, water and broth. Bring to a boil and cook for 5 minutes.
5. Add the pasta and cook uncovered, stirring often so it doesn''t stick, until tender (check the package time).
6. Off the heat, stir in the parmesan and parsley, adding a little water if it got too thick. Top each bowl with the saved bacon.', 15, 35, 6, '$', array[]::text[], 'https://www.budgetbytes.com/pasta-e-fagioli/', 'https://images.unsplash.com/photo-1680420572234-1acdf5b8fb89?auto=format&fit=crop&w=1200&q=80', 'Photo by Corryn Burtenshaw on Unsplash'),
  ('Turkey Chili', 'American', '1. Cook the turkey in the olive oil in a large pot over medium heat, breaking it up, until no longer pink.
2. Meanwhile, dice the onion and poblano and mince the garlic. Add them to the pot and cook until the onion is soft.
3. Drain and rinse the beans. Add them to the pot with the corn, tomatoes, tomato paste, all the spices, salt, pepper and water, and stir until the paste dissolves.
4. Cover and bring to a simmer, then lower the heat to medium-low and simmer for 30 minutes, stirring now and then. Adjust the salt and serve with your favorite toppings.', 10, 40, 6, '$', array[]::text[], 'https://www.budgetbytes.com/turkey-chili/', 'https://images.unsplash.com/photo-1729450412050-6c00ec592e34?auto=format&fit=crop&w=1200&q=80', 'Photo by Maria Klichik on Unsplash'),
  ('Minestrone Soup', 'Italian', '1. Heat the oil in a large pot over medium heat. Add the chopped onion, carrots, celery, salt and some pepper and cook for about 8 minutes, stirring now and then, until soft.
2. Add the garlic, tomatoes, beans, chopped green beans, broth, bay leaves, oregano and thyme. Cover and simmer for 20 minutes.
3. Stir in the pasta and cook uncovered for about 10 minutes, until tender.
4. Remove the bay leaves, season to taste and serve topped with parsley, pepper flakes and parmesan if you like (skip the parmesan to make it vegan).', 15, 30, 4, '$', array['vegetarian']::text[], 'https://www.loveandlemons.com/minestrone-soup/', 'https://images.unsplash.com/photo-1611068120813-eca5a8cbf793?auto=format&fit=crop&w=1200&q=80', 'Photo by Nathan Dumlao on Unsplash'),
  ('Blueberry Overnight Oats', 'American', '1. Jam: simmer 3 cups of the blueberries with 1 tbsp lemon juice and the vanilla in a saucepan over medium heat for 3 to 5 minutes, mashing as they soften. Off the heat, stir in the maple syrup, cinnamon, chia seeds and salt, and let it thicken for 10 minutes. It makes extra and keeps for about a week in the fridge.
2. Divide the oats and almond milk among 4 jars (1/2 cup of each per jar).
3. Top each jar with 1 tbsp jam, a handful of the remaining blueberries and some grated lemon zest.
4. Cover and refrigerate overnight. Eat cold in the morning.', 10, 5, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.loveandlemons.com/overnight-oats/', 'https://images.unsplash.com/photo-1490371475955-4cb3bfc72f71?auto=format&fit=crop&w=1200&q=80', 'Photo by Alisha Hieb on Unsplash'),
  ('Banana Pancakes', 'American', '1. In a large bowl, mix the flour, sugar, baking powder, baking soda, cinnamon, salt and nutmeg.
2. In another bowl, whisk 1 cup mashed banana with the egg, milk, oil and vanilla. Stir it into the dry ingredients until just combined. A few lumps are fine.
3. Heat a nonstick skillet over medium-low heat and brush it with a little oil. Pour in 1/3 cup batter per pancake.
4. Cook for about 2 minutes, until bubbles form and the edges look set, then flip and cook 1 to 2 minutes more.
5. Serve warm with maple syrup and sliced banana.', 10, 20, 4, '$', array['vegetarian']::text[], 'https://www.loveandlemons.com/banana-pancakes/', 'https://images.unsplash.com/photo-1528207776546-365bb710ee93?auto=format&fit=crop&w=1200&q=80', 'Photo by nikldn on Unsplash'),
  ('Air Fryer Salmon Patties', 'American', '1. Line the air fryer basket with parchment or spray it with oil.
2. Mix the eggs, chopped onion, dill, mayo, mustard and Old Bay in a bowl. Add the flaked salmon and the panko and stir until combined.
3. Freeze the mixture for 10 minutes so it holds together, then shape it into 6 firm patties.
4. Spray the patties with oil and air fry at 400°F for 8 to 10 minutes, flipping halfway, until golden.
5. Serve with lemon wedges over greens, in a bun or in a bowl.', 15, 10, 3, '$$', array['pescatarian']::text[], 'https://www.skinnytaste.com/air-fryer-salmon/', 'https://images.unsplash.com/photo-1607877200924-1762edf69437?auto=format&fit=crop&w=1200&q=80', 'Photo by Carlos Perales on Unsplash'),
  ('Air Fryer Chicken Thighs', 'American', '1. Pat the bone-in chicken thighs dry. Squeeze half the lemon over them, then season both sides with the salt, pepper, garlic powder, onion powder, paprika and herbs, rubbing them in well.
2. Place the thighs skin-side down in the air fryer basket in one layer.
3. Air fry at 400°F for 12 minutes, flip, and cook for about 12 minutes more, until the skin is crisp and the inside reaches 165°F.
4. Serve with the remaining lemon cut into wedges.', 5, 24, 6, '$', array[]::text[], 'https://www.skinnytaste.com/air-fryer-chicken-thighs/', 'https://images.unsplash.com/photo-1610057099443-fde8c4d50f91?auto=format&fit=crop&w=1200&q=80', 'Photo by Nathan Dumlao on Unsplash'),
  ('Shrimp Scampi with Pasta', 'Italian', '1. Cook the pasta in well-salted boiling water until al dente. Save 1 cup of the cooking water, then drain.
2. Meanwhile, heat the oil in a large skillet over medium heat and cook the sliced shallots for 1 minute.
3. Add the sliced garlic, pepper flakes, peeled shrimp and a pinch of salt and pepper. Cook, stirring, until the shrimp are just pink, 2 to 3 minutes. Move the shrimp to a plate.
4. Pour the wine into the pan and simmer until reduced by half, 3 to 4 minutes.
5. Add the butter, 3 tbsp lemon juice, 1 tsp lemon zest and 1/2 cup pasta water and stir until the butter melts. Toss in the pasta.
6. Return the shrimp and their juices, add the parsley and toss. Loosen with more pasta water if needed and season to taste.', 15, 20, 4, '$$$', array['pescatarian']::text[], 'https://www.onceuponachef.com/recipes/shrimp-scampi.html', 'https://images.unsplash.com/photo-1677681483419-e18aa1376db7?auto=format&fit=crop&w=1200&q=80', 'Photo by Ellie Ellien on Unsplash'),
  ('Spaghetti Aglio e Olio', 'Italian', '1. Bring a big pot of water to a boil with 2 tsp of the salt and cook the spaghetti for 1 minute less than the package says.
2. Just before draining, scoop out 1 cup of the cooking water, then drain the pasta.
3. About 4 minutes before the pasta is done, warm the oil in a large, deep pan over medium heat. Add the thinly sliced garlic and cook it slowly until pale golden (don''t let it brown), then add the pepper flakes.
4. Add the drained pasta, 1/2 cup cooking water and the remaining salt and toss hard over medium-high heat until the sauce turns silky and clings to the pasta.
5. Toss in the chopped parsley and serve right away with grated parmesan (skip it to make the dish vegan).', 5, 12, 4, '$', array['vegetarian']::text[], 'https://www.recipetineats.com/aglio-e-olio-garlic-spaghetti/', 'https://images.unsplash.com/photo-1576698961137-6832c546e321?auto=format&fit=crop&w=1200&q=80', 'Photo by Christine Sandu on Unsplash'),
  ('Mujaddara (Lentils and Rice with Caramelized Onions)', 'Middle Eastern', '1. Thinly slice the onions and cook them in the olive oil in a large pot over low heat for about an hour, stirring often, until deep brown and sweet. Set aside about a third of them for the topping.
2. Add the cumin, allspice and cloves to the onions left in the pot and stir for 1 minute, then pour in the broth.
3. Add the rice and rinsed lentils, cover and bring to a boil over high heat. Turn the heat to low and simmer, covered, for about 30 minutes, until the liquid is absorbed and the lentils are tender.
4. Fluff with a fork, season with salt if needed and serve topped with the reserved onions.', 10, 100, 6, '$', array['vegan', 'vegetarian']::text[], 'https://www.budgetbytes.com/mujaddara/', 'https://images.unsplash.com/photo-1788603092417-a01e665e0ab2?auto=format&fit=crop&w=1200&q=80', 'Photo by Zoshua Colah on Unsplash'),
  ('Korean Beef Bulgogi Rice Bowls', 'Korean', '1. Bulgogi sauce: finely grate the onion, apple, garlic and ginger into a paste and mix with 2 1/2 tbsp soy sauce, 1 tbsp sesame oil, the mirin, 1 tbsp brown sugar and the pepper. Drizzle: in another bowl, mix 2 tbsp soy sauce, 1 tbsp sesame oil, 2 tsp brown sugar and the rice vinegar.
2. Heat 2 tsp oil in a large nonstick pan over high heat and wilt the spinach in two batches. Set aside.
3. Add 1 tbsp oil and the beef and cook, breaking it up, until browned. Pour in the bulgogi sauce and cook until it''s absorbed and the beef caramelizes a little.
4. Fill bowls with cooked rice, then the beef, spinach, grated carrot, mashed avocado, pickled ginger and shredded lettuce. Finish with the drizzle, sesame seeds and sliced green onion.', 15, 10, 4, '$$', array[]::text[], 'https://www.recipetineats.com/korean-beef-bulgogi-rice-bowls-the-easy-way/', 'https://images.unsplash.com/photo-1682566509568-ded8649b26bb?auto=format&fit=crop&w=1200&q=80', 'Photo by Xavier Chng on Unsplash'),
  ('Greek Salad', 'Greek', '1. Whisk the olive oil, vinegar, grated garlic, oregano, mustard, salt and a few grinds of pepper.
2. Cut the cucumber and green bell pepper into bite-size chunks and halve the tomatoes.
3. Arrange the vegetables, feta, thinly sliced red onion and olives on a platter, drizzle with the dressing and scatter the mint on top.', 15, 0, 4, '$$', array['vegetarian']::text[], 'https://www.loveandlemons.com/greek-salad/', 'https://images.unsplash.com/photo-1769481614068-47cfb4d1f125?auto=format&fit=crop&w=1200&q=80', 'Photo by william wallace on Unsplash'),
  ('Vegetable Fried Rice', 'Chinese', '1. Heat a little of the oil in a large skillet over medium heat and scramble the eggs for about 1 minute. Set them aside.
2. Wipe the pan, add 1 tbsp oil and cook the diced onion, diced carrots and frozen peas for about 5 minutes, until soft.
3. Add the remaining oil with the garlic, ginger and the white parts of the green onions for 30 seconds. Add the cold cooked rice, the soy sauce and 1 tbsp sesame oil and fry, stirring, for a few minutes, until the rice is hot and a little crispy.
4. Stir in the rest of the sesame oil, the rice vinegar and the eggs. Season to taste and top with the green onion tops. Rice cooked the day before works best.', 5, 10, 4, '$', array['vegetarian']::text[], 'https://www.loveandlemons.com/fried-rice/', 'https://images.unsplash.com/photo-1603133872878-684f208fb84b?auto=format&fit=crop&w=1200&q=80', 'Photo by Christopher Alvarenga on Unsplash'),
  ('Vegan Burrito Bowls', 'Mexican', '1. Cook the rice, then stir in the juice of 1 lime, the chopped cilantro and a pinch of salt.
2. Tofu sofritas: crumble the tofu into a skillet with 1 tbsp hot oil and cook over medium-high heat for about 8 minutes, until golden. Stir in the minced chipotles with a spoonful of their sauce, the tomato paste, cumin, a pinch of salt and a splash of water, and cook 2 minutes more.
3. Fajita veggies: slice the peppers and onion and cook them in the remaining oil over high heat for 6 to 8 minutes, until charred at the edges. Salt to taste.
4. Warm the beans with a pinch of salt.
5. Fill bowls with rice, beans, sofritas and veggies, then top with salsa, sliced avocado and lime wedges.', 20, 30, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.loveandlemons.com/burrito-bowl/', 'https://images.unsplash.com/photo-1668665771757-4d42737d295a?auto=format&fit=crop&w=1200&q=80', 'Photo by Andrew Relf on Unsplash'),
  ('Black Bean Tacos', 'Mexican', '1. Heat the oil in a skillet over medium heat. Cook the diced onion, 1 minced jalapeño, the garlic and the salt, stirring, for 5 to 8 minutes, until soft.
2. Stir in the taco seasoning and cayenne for 1 minute. Add the beans and about 1/4 cup of their liquid (or water) and simmer for 5 minutes.
3. Mash some of the beans with a spoon so the mixture turns creamy, then stir in 1 tbsp lime juice and season to taste.
4. Warm the tortillas and fill them with the beans, shredded cabbage, sour cream mixed with a squeeze of lime, cotija, the other jalapeño (sliced) and cilantro.', 15, 15, 4, '$', array['vegetarian']::text[], 'https://www.loveandlemons.com/black-bean-tacos/', 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=1200&q=80', 'Photo by Chad Montano on Unsplash'),
  ('Garlic Butter Shrimp', 'Australian', '1. Toss the peeled shrimp with 1 tbsp oil and the pepper and let them sit for 20 minutes. Sprinkle with the salt just before cooking.
2. Heat 1 tbsp oil in a large nonstick pan over high heat. Sear half the shrimp for about 1 minute per side and move them to a plate. Repeat with the last 1 tbsp oil and the rest of the shrimp.
3. Put all the shrimp back in the pan, add the minced garlic and stir for 30 seconds.
4. Pour in the wine and let it bubble, scraping the pan, until mostly evaporated (about 30 seconds).
5. Add the butter and 1 tbsp lemon juice and swirl until melted, then toss in the parsley. Serve with lemon wedges and bread to soak up the sauce.', 10, 6, 4, '$$$', array['pescatarian']::text[], 'https://www.recipetineats.com/garlic-prawns/', 'https://images.unsplash.com/photo-1625943553852-781c6dd46faa?auto=format&fit=crop&w=1200&q=80', 'Photo by Farhad Ibrahimzade on Unsplash'),
  ('Air Fryer Falafel', 'Middle Eastern', '1. Soak the dried chickpeas in plenty of water overnight, then drain and pat them dry. Canned chickpeas make mushy falafel.
2. Pulse the onion, garlic, herbs, green onions, cumin, salt and pepper flakes in a food processor until finely chopped.
3. Add the chickpeas and pulse a few times, until coarsely ground but not a paste. Add the baking powder and flour and pulse 2 or 3 more times.
4. Cover and refrigerate for 2 to 3 hours so the mixture firms up, then shape it into 12 balls (flour your hands if it''s sticky).
5. Heat the air fryer to 350°F. Spray the falafel with oil and cook in batches for about 14 minutes, turning halfway, until golden.
6. Serve in pita with hummus, tomato, cucumber and tahini.', 15, 30, 4, '$', array['vegan', 'vegetarian']::text[], 'https://www.skinnytaste.com/air-fryer-falafel/', 'https://images.unsplash.com/photo-1593001872095-7d5b3868fb1d?auto=format&fit=crop&w=1200&q=80', 'Photo by Anton on Unsplash'),
  ('Baked Mac and Cheese', 'American', '1. Heat the oven to 425°F and grease a 9x13-inch baking dish. Toss the panko with the olive oil and parmesan.
2. Cook the macaroni in salted boiling water for 1 minute less than the package says, then drain.
3. Melt the butter in a large pot over medium heat, whisk in the flour and cook for 1 to 2 minutes, until lightly golden. Slowly whisk in the milk and keep whisking until it thickens enough to coat a spoon, 5 to 8 minutes. Whisk in the grated garlic, mustard, paprika and salt.
4. Turn the heat to low and add the grated cheddar and Gruyère a handful at a time, whisking until smooth. Season with pepper and stir in the pasta.
5. Pour into the dish, sprinkle with the panko and bake for 15 to 20 minutes, until golden and bubbling.', 15, 45, 8, '$$', array['vegetarian']::text[], 'https://www.loveandlemons.com/mac-and-cheese/', 'https://images.unsplash.com/photo-1667499989723-c4ab9549d63c?auto=format&fit=crop&w=1200&q=80', 'Photo by Leanna Myers on Unsplash'),
  ('Sweet Potato Tacos with Lime Crema', 'Mexican', '1. Crema: mix the sour cream with 1 minced garlic clove, the lime zest and juice and 1/4 tsp salt. Chill it while you cook.
2. Peel and dice the sweet potatoes small. Cook them with the oil and 2 minced garlic cloves in a large skillet over medium heat, stirring often, until tender, about 15 minutes. Add a splash of water if they stick.
3. Add the drained beans, cumin and the rest of the salt and some pepper, and cook until hot.
4. Stir in the sliced green onions and chopped cilantro.
5. Toast the tortillas in a dry skillet, fill them with the sweet potato mixture and top with the crema.', 20, 20, 4, '$', array['vegetarian']::text[], 'https://www.budgetbytes.com/sweet-potato-tacos-with-lime-crema/', 'https://images.unsplash.com/photo-1551504734-5ee1c4a1479b?auto=format&fit=crop&w=1200&q=80', 'Photo by Krisztian Tabori on Unsplash'),
  ('Classic Omelette', 'French', '1. Whisk the eggs in a bowl until the whites and yolks are fully mixed. Season with salt and pepper.
2. Heat an 8-inch nonstick skillet over medium heat and melt the butter, swirling to coat the pan.
3. Pour in the eggs. As the edges set, gently push them toward the center with a spatula and tilt the pan so the raw egg flows underneath.
4. When the top is almost set, scatter the cheese and spinach (or any filling you like) over one half, fold the other half over and slide it onto a plate.', 5, 5, 1, '$', array['vegetarian']::text[], 'https://www.loveandlemons.com/omelette/', 'https://images.unsplash.com/photo-1510693206972-df098062cb71?auto=format&fit=crop&w=1200&q=80', 'Photo by Eaters Collective on Unsplash')
) as v (title, cuisine, instructions, prep_minutes, cook_minutes, base_servings,
        cost_bracket, diet_tags, source_url, image_url, image_credit)
where not exists (
  select 1 from public.recipes r where r.source_type = 'seed' and r.title = v.title
);

